using UnityEngine;
using LWS.TruckSports;
namespace LWS.TruckBaseJumping {
public sealed class BaseJumper:MonoBehaviour {
 public BaseJumpMatch match;public SportsEventTruck truck;public int slot;public Transform canopy;public LineRenderer[] lines;public ParticleSystem crash;
 public bool Released{get;private set;}public float FlightTime{get;private set;}public bool Deployed{get;private set;}public bool Landed{get;private set;}public float Opening{get;private set;}public BaseLanding Landing{get;private set;}public Vector3 Incoming{get;private set;}public Vector3 IncomingUp{get;private set;}=Vector3.up;public string Outcome{get;private set;}="STAGED";
 MaterialPropertyBlock canopyColor;float deploymentAge;bool flareReady;Vector2 command;public bool Flaring{get;private set;}
 static readonly Vector3[] Harness={new Vector3(-.5f,.45f,-.9f),new Vector3(.5f,.45f,-.9f),new Vector3(-.5f,.45f,.9f),new Vector3(.5f,.45f,.9f)};
 public void Prepare(Vector3 p){if(canopyColor==null)canopyColor=new MaterialPropertyBlock();canopyColor.SetColor("_BaseColor",match.setup.players[slot].color);canopy.GetComponent<Renderer>().SetPropertyBlock(canopyColor,0);truck.slot=slot;truck.Prepare(p,Quaternion.identity,false);truck.body.isKinematic=true;truck.body.detectCollisions=false;Released=Deployed=Landed=Flaring=flareReady=false;FlightTime=0;Opening=deploymentAge=0;Landing=default;Outcome="STAGED";canopy.gameObject.SetActive(false);foreach(var line in lines)line.enabled=false;crash.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 public void Release(){Released=true;FlightTime=0;truck.body.isKinematic=false;truck.body.detectCollisions=true;truck.body.linearVelocity=new Vector3(0,-2,-2);truck.body.angularVelocity=new Vector3(.35f,slot%2==0?.12f:-.12f,.22f);Outcome="FREEFALL";}
 public void Step(Vector2 input,bool action,bool held,float dt,Vector3 wind){if(Landed||!Released)return;FlightTime+=dt;command=Vector2.ClampMagnitude(input,1);if(action&&!Deployed){Deployed=true;deploymentAge=0;flareReady=false;canopy.gameObject.SetActive(true);foreach(var line in lines)line.enabled=true;match.feedback.Play(4,0,true);match.Pulse(slot,.2f,.1f);}if(Deployed){deploymentAge+=dt;Opening=Mathf.SmoothStep(0,1,Mathf.Clamp01(deploymentAge/1.15f));if(!held)flareReady=true;}Flaring=Deployed&&Opening>.8f&&flareReady&&held;var body=truck.body;var velocity=body.linearVelocity;float coupling=Mathf.Lerp(.18f,.65f,Opening);float steer=Mathf.Lerp(3.2f,8.5f,Opening);var flat=new Vector3(velocity.x,0,velocity.z);body.AddForce((wind-flat)*coupling+new Vector3(command.x,0,command.y)*steer-flat*(Flaring?.65f:0),ForceMode.Acceleration);float verticalDrag=Mathf.Lerp(.18f,2.2f,Opening)+(Flaring?1:0);body.AddForce(Vector3.up*(-velocity.y*verticalDrag),ForceMode.Acceleration);var up=body.rotation*Vector3.up;var desired=new Vector3(-command.x*.25f,1,-command.y*.18f).normalized;float arrest=Mathf.SmoothStep(0,1,Opening);body.AddTorque(Vector3.Cross(up,desired)*Mathf.Lerp(.22f,9,arrest)-body.angularVelocity*Mathf.Lerp(.035f,2.2f,arrest)+new Vector3(command.y*.6f,command.x*.12f,-command.x*.65f)*(1-arrest)+new Vector3(wind.z,0,-wind.x)*.035f,ForceMode.Acceleration);Incoming=velocity;IncomingUp=body.rotation*Vector3.up;Outcome=Deployed?Opening<1?"CANOPY OPENING":Flaring?"FLARING":"CANOPY OPEN":"FREEFALL";
  var p=body.position;if(p.y< -15||Mathf.Abs(p.x)>175||Mathf.Abs(p.z)>175||FlightTime>110)Fail("OUT OF AREA / BOUNDED RECOVERY");}
 void OnCollisionEnter(Collision c){if(c.collider==match.ground&&!Landed&&match.Phase==BaseJumpPhase.Flight)Touchdown();}
 void Touchdown(){if(Landed)return;var body=truck.body;var p=body.position;float error=new Vector2(p.x-match.target.position.x,p.z-match.target.position.z).magnitude;bool valid=BaseJumpRules.Safe(Deployed,Opening,Incoming,IncomingUp);Landed=true;Landing=new BaseLanding{valid=valid,inside=error<=match.targetRadius,errorMillimetres=Mathf.RoundToInt(error*1000),timeMilliseconds=Mathf.RoundToInt(FlightTime*1000),verticalSpeed=-Incoming.y,planarSpeed=new Vector2(Incoming.x,Incoming.z).magnitude,up=Vector3.Dot(IncomingUp,Vector3.up)};Outcome=valid?Landing.inside?"SAFE · INSIDE TARGET":"SAFE · OUTSIDE TARGET":"CRASH · INVALID";truck.Power(false);if(!valid){crash.transform.position=p;crash.Play();match.feedback.Play(2,0,true);}else match.feedback.Play(5,0,true);match.Pulse(slot,valid?.25f:.55f,.18f);match.LandingLocked(this);}
 public void Fail(string reason){if(Landed)return;Landed=true;var p=truck.body.position;Landing=new BaseLanding{valid=false,errorMillimetres=Mathf.RoundToInt(new Vector2(p.x,p.z).magnitude*1000),timeMilliseconds=Mathf.RoundToInt(FlightTime*1000)};Outcome=reason;truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;canopy.gameObject.SetActive(false);foreach(var line in lines)line.enabled=false;match.LandingLocked(this);}
 public void AssignRank(BaseLanding result){Landing=result;}
 public void Draw(float dt){if(!Deployed||!canopy.gameObject.activeSelf)return;float scale=Landed?Mathf.MoveTowards(canopy.localScale.x,0,dt):Opening;canopy.localScale=Vector3.one*scale;if(scale<=.01f&&Landed){canopy.gameObject.SetActive(false);foreach(var line in lines)line.enabled=false;return;}canopy.position=truck.body.position+Vector3.up*(6.5f*scale)+match.weatherField.Flow*.025f;canopy.rotation=Quaternion.Slerp(canopy.rotation,Quaternion.Euler(command.y*8,0,-command.x*12),1-Mathf.Exp(-dt*5));for(int i=0;i<4;i++){lines[i].SetPosition(0,truck.transform.TransformPoint(Harness[i]));lines[i].SetPosition(1,canopy.TransformPoint(new Vector3(i%2==0?-3.2f:3.2f,0,i<2?-2.5f:2.5f)));}}
}
}
